import{_ as r,a0 as p,w as n,s,ao as i,I as u,a1 as e,A as l,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"新面孔、新功能的 Tomahawk 音樂播放器 | LCTT x X-CMD","titleTemplate":false,"description":"新面孔、新功能的 Tomahawk 音樂播放器 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"新面孔、新功能的 Tomahawk 音樂播放器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"新面孔、新功能的 Tomahawk 音樂播放器 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141106 Tomahawk Music Player Returns With New Look, Features","title":"新面孔、新功能的 Tomahawk 音樂播放器","tag":"201503","desc":""},"relativePath":"201503/20141106 Tomahawk Music Player Returns With New Look, Features.md","filePath":"[post].md"}'),m={name:"201503/20141106 Tomahawk Music Player Returns With New Look, Features.md"};function h(w,a,k,d,T,f){const o=p("Link");return n(),s("div",null,[a[14]||(a[14]=i(`<h1 id="新面孔、新功能的-tomahawk-音樂播放器" tabindex="-1">新面孔、新功能的 Tomahawk 音樂播放器 <a class="header-anchor" href="#新面孔、新功能的-tomahawk-音樂播放器" aria-label="Permalink to “新面孔、新功能的 Tomahawk 音樂播放器”">​</a></h1><p>**在悄無聲息得過了一年之後，Tomahawk——音樂播放器中的瑞士軍刀——帶着值得歌頌的全新發行版迴歸了。 **</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/tomahawk-tile-1.jpg" alt=""></p><p>這個0.8版的開源跨平台應用增添了<strong>更多在線服務的支持</strong>，更新了它的外觀，又一次確保了它創新的社交功能完美運行。</p><h3 id="tomahawk——兩個世界的極品" tabindex="-1">Tomahawk——兩個世界的極品 <a class="header-anchor" href="#tomahawk——兩個世界的極品" aria-label="Permalink to “Tomahawk——兩個世界的極品”">​</a></h3><p>Tomahawk 將一個傳統的應用結構與我們的“即時”現代文化相結合。它可以瀏覽和播放本地的音樂和Spotify、Grooveshark以及SoundCloud這類的線上音樂。在最新的發行版中，它把Google Play Music和Beats Music列入了它的名冊。</p><p>這可能聽着很繁複或令人困惑，但實際上它表現得出奇的好。</p><p>若你想要播放一首歌，而且不介意它是從哪裏來的，你只需告訴Tomahawk這個音樂的標題和作者，它就會自動從可獲取的源裏找出高品質版本的音樂——你不需要做任何事。</p><p><img src="http://i.imgur.com/nk5oixy.jpg" alt=""></p><p>這個應用還弄了一些附加的功能，比如EchoNest剖析，Last.fm建議，還有對Jabber的支持，這樣你就能“播放”朋友的音樂。它還有一個內置的信息服務，以便於你能和其他人快速的分享播放列表和音樂。</p><blockquote><p>“這種從根本上就與眾不同的聽音樂的方式，開啓了前所未有的音樂的消費和分享體驗”，該項目的網站上這樣寫道。而且即便它如此獨特，這也沒有錯。</p></blockquote><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/tomahawk-controllers.jpg" alt="Tomahawk supports the Sound Menu"></p><p><em>支持聲音菜單</em></p><h3 id="tomahawk0-8發行版的亮點" tabindex="-1">Tomahawk0.8發行版的亮點 <a class="header-anchor" href="#tomahawk0-8發行版的亮點" aria-label="Permalink to “Tomahawk0.8發行版的亮點”">​</a></h3><ul><li>新的交互界面</li><li>對Beats Music的支持</li><li>對Google Play Music的支持（保存的和播放全部鏈接）</li><li>支持拖拽iTunes，Spotify這類網站的鏈接</li><li>正在播放的提示</li><li>Android應用（測試版）</li><li>收件箱的改進</li></ul><h3 id="在ubuntu上安裝tomahawk0-8" tabindex="-1">在Ubuntu上安裝Tomahawk0.8 <a class="header-anchor" href="#在ubuntu上安裝tomahawk0-8" aria-label="Permalink to “在Ubuntu上安裝Tomahawk0.8”">​</a></h3><p>作為一個流媒體音樂的粉絲，我會在接下來的幾天裏體驗一下這個應用軟件，然後提供一個關於他的改變的更全面的賞析。與此同時，你也可以嚐嚐鮮。</p><p>在Ubuntu 14.04 LTS和Ubuntu 14.10上可以通過官方PPA獲得Tomahawk。</p><pre><code>sudo add-apt-repository ppa:tomahawk/ppa 

sudo apt-get update &amp;&amp; sudo apt-get install tomahawk
</code></pre><p>在官方項目網站上可以找的獨立安裝程序和更詳細的信息。</p>`,20)),u("ul",null,[u("li",null,[e(o,{href:"http://gettomahawk.com/"},{default:l(()=>[...a[0]||(a[0]=[t("訪問 Tomahawk 官網",-1)])]),_:1})])]),a[15]||(a[15]=u("hr",null,null,-1)),u("p",null,[a[2]||(a[2]=t("via: ",-1)),e(o,{href:"http://www.omgubuntu.co.uk/2014/11/tomahawk-media-player-returns-new-look-features"},{default:l(()=>[...a[1]||(a[1]=[t("http://www.omgubuntu.co.uk/2014/11/tomahawk-media-player-returns-new-look-features",-1)])]),_:1})]),u("p",null,[a[6]||(a[6]=t("作者：",-1)),e(o,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:l(()=>[...a[3]||(a[3]=[t("Joey-Elijah Sneddon",-1)])]),_:1}),a[7]||(a[7]=t(" 譯者：",-1)),e(o,{href:"https://github.com/H-mudcup"},{default:l(()=>[...a[4]||(a[4]=[t("H-mudcup",-1)])]),_:1}),a[8]||(a[8]=t(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:l(()=>[...a[5]||(a[5]=[t("wxy",-1)])]),_:1})]),u("p",null,[a[11]||(a[11]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[9]||(a[9]=[t("LCTT",-1)])]),_:1}),a[12]||(a[12]=t(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:l(()=>[...a[10]||(a[10]=[t("Linux中國",-1)])]),_:1}),a[13]||(a[13]=t(" 榮譽推出",-1))])])}const C=r(m,[["render",h]]);export{x as __pageData,C as default};
